using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{public void Execute(ExecutionResult result){result.Log("playing="+EditorApplication.isPlaying+" compiling="+EditorApplication.isCompiling+" scene="+SceneManager.GetActiveScene().path+" dirty="+SceneManager.GetActiveScene().isDirty);if(EditorApplication.isPlaying)return;for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved user scene");var s=EditorSceneManager.OpenScene("Assets/Scenes/Enroth_Linked_OpenWorld.unity",OpenSceneMode.Single);var ps=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MMThirdPersonController>(true)).ToArray();foreach(var p in ps.Where(p=>p.gameObject.activeInHierarchy)){var cc=p.GetComponent<CharacterController>();var a=p.animator;result.Log("active="+p.name+" pos="+p.transform.position.ToString("R")+" rot="+p.transform.rotation.ToString("R")+" scale="+p.transform.localScale.ToString("R")+" cc="+cc.height+" center="+cc.center+" visual="+(p.visualRoot?p.visualRoot.name:"NULL")+" visualScale="+(p.visualRoot?p.visualRoot.localScale.ToString("R"):"")+" avatar="+(a&&a.avatar?a.avatar.name:"NULL")+" valid="+(a&&a.avatar&&a.avatar.isValid)+" human="+(a&&a.avatar&&a.avatar.isHuman)+" rootMotion="+(a&&a.applyRootMotion));foreach(var r in p.GetComponentsInChildren<Renderer>())result.Log("renderer="+r.name+" bounds="+r.bounds+" mats="+string.Join(";",r.sharedMaterials.Select(m=>m?m.name:"NULL")));File.WriteAllText("Validation/Hero/root_before.json",EditorJsonUtility.ToJson(p.transform,true));File.WriteAllText("Validation/Hero/controller_before.json",EditorJsonUtility.ToJson(cc,true));}result.Log("players="+ps.Length+" active="+ps.Count(p=>p.gameObject.activeInHierarchy));}}
